45: export class AbortError extends Error {
46: 	constructor(message) {
47: 		super();
48: 
49: 		if (message instanceof Error) {
50: 			this.originalError = message;
51: 			({message} = message);
52: 		} else {
53: 			this.originalError = new Error(message);
54: 			this.originalError.stack = this.stack;
55: 		}
56: 
57: 		this.name = 'AbortError';
58: 		this.message = message;
59: 	}
60: }
