62: function calculateDelay(retriesConsumed, options) {
63: 	const attempt = Math.max(1, retriesConsumed + 1);
64: 	const random = options.randomize ? (Math.random() + 1) : 1;
65: 
66: 	let timeout = Math.round(random * options.minTimeout * (options.factor ** (attempt - 1)));
67: 	timeout = Math.min(timeout, options.maxTimeout);
68: 
69: 	return timeout;
70: }
71: 
72: function calculateRemainingTime(start, max) {
73: 	if (!Number.isFinite(max)) {
74: 		return max;
75: 	}
76: 
77: 	return max - (performance.now() - start);
78: }
