80: async function delayForRetry(delay, options) {
81: 	if (delay <= 0) {
82: 		return;
83: 	}
84: 
85: 	await new Promise((resolve, reject) => {
86: 		const onAbort = () => {
87: 			clearTimeout(timeoutToken);
88: 			options.signal?.removeEventListener('abort', onAbort);
89: 			reject(options.signal.reason);
90: 		};
91: 
92: 		const timeoutToken = setTimeout(() => {
93: 			options.signal?.removeEventListener('abort', onAbort);
94: 			resolve();
95: 		}, delay);
96: 
97: 		if (options.unref) {
98: 			timeoutToken.unref?.();
99: 		}
100: 
101: 		options.signal?.addEventListener('abort', onAbort, {once: true});
102: 	});
103: }
