105: async function onAttemptFailure({error, attemptNumber, retriesConsumed, startTime, options}) {
106: 	const normalizedError = error instanceof Error
107: 		? error
108: 		: new TypeError(`Non-error was thrown: "${error}". You should only throw errors.`);
109: 
110: 	if (normalizedError instanceof AbortError) {
111: 		throw normalizedError.originalError;
112: 	}
113: 
114: 	const retriesLeft = Number.isFinite(options.retries)
115: 		? Math.max(0, options.retries - retriesConsumed)
116: 		: options.retries;
117: 
118: 	const maxRetryTime = options.maxRetryTime ?? Number.POSITIVE_INFINITY;
119: 	const delayTime = calculateDelay(retriesConsumed, options);
120: 	const remainingTimeBeforeCallbacks = calculateRemainingTime(startTime, maxRetryTime);
121: 
122: 	if (remainingTimeBeforeCallbacks <= 0) {
123: 		const context = Object.freeze({
124: 			error: normalizedError,
125: 			attemptNumber,
126: 			retriesLeft,
127: 			retriesConsumed,
128: 			retryDelay: 0,
129: 		});
130: 
131: 		await options.onFailedAttempt(context);
132: 
133: 		throw normalizedError;
134: 	}
135: 
136: 	const consumeRetryContext = Object.freeze({
137: 		error: normalizedError,
138: 		attemptNumber,
139: 		retriesLeft,
140: 		retriesConsumed,
141: 		retryDelay: retriesLeft > 0 ? delayTime : 0,
142: 	});
143: 
144: 	const consumeRetry = await options.shouldConsumeRetry(consumeRetryContext);
145: 	const effectiveDelay = consumeRetry && retriesLeft > 0 ? delayTime : 0;
146: 	const context = Object.freeze({
147: 		error: normalizedError,
148: 		attemptNumber,
149: 		retriesLeft,
150: 		retriesConsumed,
151: 		retryDelay: effectiveDelay,
152: 	});
153: 
154: 	await options.onFailedAttempt(context);
155: 
156: 	if (calculateRemainingTime(startTime, maxRetryTime) <= 0) {
157: 		throw normalizedError;
158: 	}
159: 
160: 	const remainingTime = calculateRemainingTime(startTime, maxRetryTime);
161: 
162: 	if (remainingTime <= 0 || retriesLeft <= 0) {
163: 		throw normalizedError;
164: 	}
165: 
166: 	if (normalizedError instanceof TypeError && !isNetworkError(normalizedError)) {
167: 		throw normalizedError;
168: 	}
169: 
170: 	if (!await options.shouldRetry(context)) {
171: 		throw normalizedError;
172: 	}
173: 
174: 	const remainingTimeAfterShouldRetry = calculateRemainingTime(startTime, maxRetryTime);
175: 
176: 	if (remainingTimeAfterShouldRetry <= 0) {
177: 		throw normalizedError;
178: 	}
179: 
180: 	if (!consumeRetry) {
181: 		options.signal?.throwIfAborted();
182: 		return false;
183: 	}
184: 
185: 	const finalDelay = Math.min(effectiveDelay, remainingTimeAfterShouldRetry);
186: 
187: 	options.signal?.throwIfAborted();
188: 
189: 	await delayForRetry(finalDelay, options);
190: 
191: 	options.signal?.throwIfAborted();
192: 
193: 	return true;
194: }
