196: export default async function pRetry(input, options = {}) {
197: 	options = {...options};
198: 
199: 	validateRetries(options.retries);
200: 
201: 	if (Object.hasOwn(options, 'forever')) {
202: 		throw new Error('The `forever` option is no longer supported. For many use-cases, you can set `retries: Infinity` instead.');
203: 	}
204: 
205: 	options.retries ??= 10;
206: 	options.factor ??= 2;
207: 	options.minTimeout ??= 1000;
208: 	options.maxTimeout ??= Number.POSITIVE_INFINITY;
209: 	options.maxRetryTime ??= Number.POSITIVE_INFINITY;
210: 	options.randomize ??= false;
211: 	options.onFailedAttempt ??= () => {};
212: 	options.shouldRetry ??= () => true;
213: 	options.shouldConsumeRetry ??= () => true;
214: 
215: 	// Validate numeric options and normalize edge cases
216: 	validateFunctionOption('onFailedAttempt', options.onFailedAttempt);
217: 	validateFunctionOption('shouldRetry', options.shouldRetry);
218: 	validateFunctionOption('shouldConsumeRetry', options.shouldConsumeRetry);
219: 	validateNumberOption('factor', options.factor, {min: 0, allowInfinity: false});
220: 	validateNumberOption('minTimeout', options.minTimeout, {min: 0, allowInfinity: false});
221: 	validateNumberOption('maxTimeout', options.maxTimeout, {min: 0, allowInfinity: true});
222: 	validateNumberOption('maxRetryTime', options.maxRetryTime, {min: 0, allowInfinity: true});
223: 
224: 	// Treat non-positive factor as 1 to avoid zero backoff or negative behavior
225: 	if (!(options.factor > 0)) {
226: 		options.factor = 1;
227: 	}
228: 
229: 	options.signal?.throwIfAborted();
230: 
231: 	let attemptNumber = 0;
232: 	let retriesConsumed = 0;
233: 	const startTime = performance.now();
234: 
235: 	while (Number.isFinite(options.retries) ? retriesConsumed <= options.retries : true) {
236: 		attemptNumber++;
237: 
238: 		try {
239: 			options.signal?.throwIfAborted();
240: 
241: 			const result = await input(attemptNumber);
242: 
243: 			options.signal?.throwIfAborted();
244: 
245: 			return result;
246: 		} catch (error) {
247: 			if (await onAttemptFailure({
248: 				error,
249: 				attemptNumber,
250: 				retriesConsumed,
251: 				startTime,
252: 				options,
253: 			})) {
254: 				retriesConsumed++;
255: 			}
256: 		}
257: 	}
258: 
259: 	// Should not reach here, but in case it does, throw an error
260: 	throw new Error('Retry attempts exhausted without throwing an error.');
261: }
